method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    requires forall ext | ext in extensions :: ext != ""
    ensures result == class_name + "." + strongestExtension
    ensures strongestExtension in extensions
    ensures (forall ext1, ext2 | ext1 in extensions && ext2 in extensions && ext1 != ext2 
            && strength(ext1) == strength(ext2) ==> indexOf(ext1) < indexOf(ext2) ==> strongestExtension == ext1)
{
    var strongestExtension := extensions[0];
    var highestStrength := strength(strongestExtension);

    // Iterate through the extensions to find the strongest one
    var i := 1;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant strongestExtension in extensions
        invariant highestStrength == strength(strongestExtension)
    {
        var currentExtension := extensions[i];
        var currentStrength := strength(currentExtension);
        if currentStrength > highestStrength {
            strongestExtension := currentExtension;
            highestStrength := currentStrength;
        }
        i := i + 1;
    }

    result := class_name + "." + strongestExtension;
}

// Helper function to calculate the strength of an extension
method strength(extension: string) returns (s: int)
    requires extension != ""
{
    var CAP := 0;
    var SM := 0;
    var i := 0;
    while i < |extension|
        invariant 0 <= i <= |extension|
        invariant CAP + SM == |extension|
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            CAP := CAP + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            SM := SM + 1;
        }
        i := i + 1;
    }
    s := CAP - SM;
}
